if packed and "gaussian_ids" in info and info["gaussian_ids"] is not None:
    gs_ids = info["gaussian_ids"]
    grad_norms = grads.reshape(-1, grads.shape[-1]).norm(dim=-1)
else:
    vis = info["radii"] > 0.0
    if vis.dim() == 3:
        vis = vis.all(dim=-1)
    gs_ids = torch.where(vis)[1]
    grad_norms = grads[vis].norm

if grads.dim() == 2:
    # Packed mode: grads are [nnz, 2], use gaussian_ids directly
    gs_ids = info["gaussian_ids"]
    grad_norms = grads.norm(dim=-1)
else:
    sel = info["radii"] > 0.0
    if sel.dim() == 3:
        sel = sel.all(dim=-1)
    gs_ids = torch.where(sel)[1]
    grad_norms = grads[sel].norm(dim=-1)
